import java.util.Scanner;

public class Solution {
    static final long MOD = 998244353L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long l = sc.nextLong();
        long r = sc.nextLong();

        if ((n * m) % 2 == 1) {
            System.out.println(powerMod(r - l + 1, n * m));
            return;
        }

        long evenCount = r / 2 - (l - 1) / 2;
        long oddCount = (r - l + 1) - evenCount;

        long totalWays = (powerMod(evenCount + oddCount, n * m) + powerMod(evenCount - oddCount, n * m)) % MOD;
        long invTwo = powerMod(2, MOD - 2);
        long result = (totalWays * invTwo) % MOD;

        System.out.println(result);
        sc.close();
    }

    static long powerMod(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }
}
