#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;

long long powerMod(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    if ((n * m) % 2 == 1) {
        cout << powerMod(r - l + 1, n * m) << "\n";
        return 0;
    }

    long long evenCount = r / 2 - (l - 1) / 2;
    long long oddCount = (r - l + 1) - evenCount;

    long long totalWays = (powerMod(evenCount + oddCount, n * m) + powerMod(evenCount - oddCount, n * m)) % MOD;
    long long invTwo = powerMod(2, MOD - 2);
    long long result = (totalWays * invTwo) % MOD;

    cout << result << "\n";

    return 0;
}
